API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway container

Container_Boundary(api_gateway, "API Gateway") {
    Component(Edge Routing and Rate Limiting Component, "Edge Routing and Rate Limiting Component", "Azure API Gateway", "Handles edge routing, rate limiting, circuit breaking, and response caching for incoming traffic.")
    Component(Security and Validation Component, "Security and Validation Component", "Azure API Gateway / JWT / OAuth2", "Performs JWT/OAuth2 validation, request aggregation, and error transformation.")
    Component(Routing Control Component, "Routing Control Component", "Azure App Configuration", "Dynamically toggles claim-type routing for rapid rollback via feature flag management.")
}

Rel(Edge Routing and Rate Limiting Component, Security and Validation Component, "Validates and secures incoming requests")
Rel(Security and Validation Component, Routing Control Component, "Checks feature flags for claim-type routing")

@enduml

Anti-Corruption Layer (ACL).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(acl, "Anti-Corruption Layer (ACL)") {
    Component(ClaimTranslationComponent, "Claim Translation Component", ".NET Core / Modular Monolith", "Translates modern claim data models into legacy-compatible formats for the mainframe.")
    Component(LegacyDispatcherComponent, "Legacy Dispatcher Component", ".NET Core with Polly", "Dispatches claim data to the on-premises COBOL/DB2 mainframe using circuit breaker and resilience patterns.")
}

Rel(ClaimTranslationComponent, LegacyDispatcherComponent, "Passes translated claim payloads")

@startuml

Data Synchronization Worker.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Data Synchronization Worker container

System_Ext(Azure_Service_Bus, "Azure Service Bus", "Messaging broker for asynchronous communication.")
System_Ext(Read_Model_Cache, "Read-Model Cache", "Azure Cache / In-Memory Database providing fast read access for adjusters.")

Container_Boundary(Data_Synchronization_Worker_boundary, "Data Synchronization Worker") {
    Component(Data_Synchronization_Worker, "Data Synchronization Worker", ".NET Background Worker", "Executes asynchronous state updates, consuming and processing synchronization messages from the Azure Service Bus and updating the Read-Model Cache.")
}

Rel(Data_Synchronization_Worker, Azure_Service_Bus, "Consume and process synchronization messages", "AMQP")
Rel(Data_Synchronization_Worker, Read_Model_Cache, "Update claim states", "TCP/Redis Protocol")

@enduml

Feature Flag Management Module.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(feature_flag_management_module, "Feature Flag Management Module") {
    Component(Feature_Flag_Management_Module, "Feature Flag Management Module", "Azure App Configuration", "Dynamically controls claim-type routing between the legacy mainframe and the modern Azure platform.")
    Component(API_Gateway_and_Anti_Corruption_Layer_ACL, "API Gateway and Anti-Corruption Layer (ACL)", ".NET Core / Modular Monolith", "Routes claims and handles anti-corruption layer translation.")
    Component(Centralized_Observability_Audit_Logging_Module, "Centralized Observability & Audit Logging Module", "Azure Monitor / Application Insights", "Emits telemetry and audit logs.")
    Component(GitOps_Pipeline_and_Version_Controlled_Configuration_Repositories, "GitOps Pipeline and Version-Controlled Configuration Repositories", "Version-Controlled JSON/YAML", "Manages flags as code to prevent manual human error.")
    Component(Feature_Flag_Facade_Wrapper, "Feature Flag Facade / Wrapper", "Custom Abstraction & In-memory Caching", "Provides local caching with a 30-second TTL to ensure sub-2-second response times and circuit breaker fail-safe defaults.")
}

Rel(Feature_Flag_Management_Module, API_Gateway_and_Anti_Corruption_Layer_ACL, "Dynamically toggles claim-type routing", "REST API / Azure SDK")
Rel(Feature_Flag_Management_Module, Centralized_Observability_Audit_Logging_Module, "Emits telemetry and audit logs", "Azure Monitor")
@enduml

Centralized Observability & Audit Loggin.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Centralized Observability & Audit Logging Module container

Container_Boundary(observability_module, "Centralized Observability & Audit Logging Module") {
    Component(Telemetry_Collector, "Telemetry Collector", "Azure Monitor / Application Insights (W3C Trace Context, HTTPS)", "Receives and aggregates structured JSON logs and telemetry streams from all .NET Core modules.")
    Component(Audit_Trail_Manager, "Audit Trail Manager", "Azure Log Analytics", "Maintains compliance-ready audit trails and structured logs for system access and claim modifications.")
}

Rel(Telemetry_Collector, Audit_Trail_Manager, "Forwards structured telemetry and logs to", "")

@enduml

Database Migration & Schema Versioning M.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Database Migration & Schema Versioning Module container

Container_Boundary(db_migration_module, "Database Migration & Schema Versioning Module") {
    Component(Schema_Versioning_Runner, "Schema Versioning Runner", "Flyway", "Executes pure SQL declarative scripts for transparent, reproducible schema evolution.")
}

